200	  /// support the current project, except for fuchsia and web.
201	  ///
202	  /// * If the user specified a device id, then do nothing as the list is already
203	  /// filtered by [getDevices].
204	  ///
205	  /// * If the user did not specify a device id and there is more than one
206	  /// device connected, then filter out unsupported devices and prioritize
207	  /// ephemeral devices.
208	  Future<List<Device>> findTargetDevices(FlutterProject flutterProject) async {
209	    List<Device> devices = await getDevices();
210	
211	    // Always remove web and fuchsia devices from `--all`. This setting
212	    // currently requires devices to share a frontend_server and resident
213	    // runnner instance. Both web and fuchsia require differently configured
214	    // compilers, and web requires an entirely different resident runner.
215	    if (hasSpecifiedAllDevices) {
216	      devices = <Device>[
217	        for (final Device device in devices)
218	          if (await device.targetPlatform != TargetPlatform.fuchsia_arm64 &&
219	              await device.targetPlatform != TargetPlatform.fuchsia_x64 &&
220	              await device.targetPlatform != TargetPlatform.web_javascript)
221	            device,
222	      ];
223	    }
224	
225	    // If there is no specified device, the remove all devices which are not
226	    // supported by the current application. For example, if there was no
227	    // 'android' folder then don't attempt to launch with an Android device.
228	    if (devices.length > 1 && !hasSpecifiedDeviceId) {
229	      devices = <Device>[
230	        for (final Device device in devices)
231	          if (isDeviceSupportedForProject(device, flutterProject))
232	            device,
233	      ];
234	    } else if (devices.length == 1 &&
235	             !hasSpecifiedDeviceId &&
236	             !isDeviceSupportedForProject(devices.single, flutterProject)) {
237	      // If there is only a single device but it is not supported, then return
238	      // early.
239	      return <Device>[];
240	    }
241	
242	    // If there are still multiple devices and the user did not specify to run
243	    // all, then attempt to prioritize ephemeral devices. For example, if the
244	    // use only typed 'flutter run' and both an Android device and desktop
245	    // device are availible, choose the Android device.
246	    if (devices.length > 1 && !hasSpecifiedAllDevices) {
247	      // Note: ephemeral is nullable for device types where this is not well
248	      // defined.
249	      if (devices.any((Device device) => device.ephemeral == true)) {
250	        devices = devices
251	            .where((Device device) => device.ephemeral == true)
252	            .toList();
253	      }
254	    }
255	    return devices;
256	  }
