lobals.printStatus(globals.userMessages.flutterChooseDevice(count, device.name, device.id));\n      count++;\n    }\n  }\n\n  Future<String> _readUserInput(int deviceCount) async {\n    globals.terminal.usesTerminalUi = true;\n    final String result = await globals.terminal.promptForCharInput(\n        <String>[ for (int i = 0; i < deviceCount; i++) '$i' ],\n        logger: globals.logger,\n        prompt: globals.userMessages.flutterChooseOne);\n    return result;\n  }\n", "numLines": 55, "startLine": 242, "totalLines": 904}}
